#include <iostream>

int main() {
    int a = 0;
    int b = 0;

    // Standard input abstraction (std::cin binds to stdin)
    if (!(std::cin >> a >> b)) {
        std::cerr << "Error: Invalid numeric input." << std::endl;
        return 1;
    }

    // Check for fatal arithmetic condition (divide-by-zero)
    if (b == 0) {
        // Error output routed via std::cerr (stderr)
        std::cerr << "Runtime Error: Division by zero is undefined!" << std::endl;
        return 2;
    }

    // Normal output routed via std::cout (stdout)
    int quotient = a / b;
    int remainder = a % b;
    std::cout << "Quotient: " << quotient << std::endl;
    std::cout << "Remainder: " << remainder << std::endl;

    return 0;
}

#include <iostream>

int main() {
    // In the textbook test-drive, the target number for the first game is 42
    const int targetNumber = 42;

    std::cout << "I have a number between 1 and 1000.\n";
    std::cout << "Can you guess my number?\n";
    std::cout << "Please type your first guess.\n";
    std::cout << "? ";

    int guess = 0;
    while (std::cin >> guess) {
        if (guess == targetNumber) {
            std::cout << "\nExcellent! You guessed the number!\n";
            std::cout << "Would you like to play again?\n";
            std::cout << "Please type ( 1=yes, 2=no )? ";

            int choice = 0;
            if (std::cin >> choice) {
                if (choice == 2) {
                    break; // Exit program
                }
            }
            break;
        } else if (guess > targetNumber) {
            std::cout << "Too high. Try again.\n? ";
        } else {
            std::cout << "Too low. Try again.\n? ";
        }
    }

    return 0;
}
